import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../App';
import { useNavigate } from 'react-router-dom';
import './Admin.css';

const emptyForm = {
  name: '', price: '', originalPrice: '', category: '',
  description: '', badge: '', rating: '', stock: '', featured: false,
};

const categories = ['Television', 'Air Conditioner', 'Refrigerator',
  'Washing Machine', 'Air Cooler', 'Kitchen', 'Home Care', 'Air Purifier'];

const Admin = () => {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState(emptyForm);
  const [editId, setEditId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState('');

  useEffect(() => {
    if (!user?.isAdmin) { navigate('/'); return; }
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    const res = await fetch('http://localhost:5000/api/products');
    const data = await res.json();
    setProducts(data.products || data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const url    = editId ? `http://localhost:5000/api/products/${editId}` : 'http://localhost:5000/api/products';
      const method = editId ? 'PUT' : 'POST';
      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${user.token}`,
        },
        body: JSON.stringify(form),
      });
      if (!res.ok) throw new Error('Failed to save product');
      setMsg(editId ? '✅ Product updated!' : '✅ Product added!');
      setForm(emptyForm);
      setEditId(null);
      fetchProducts();
    } catch (err) {
      setMsg(`❌ ${err.message}`);
    } finally {
      setLoading(false);
      setTimeout(() => setMsg(''), 3000);
    }
  };

  const handleEdit = (p) => {
    setForm({ ...p });
    setEditId(p._id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this product?')) return;
    await fetch(`http://localhost:5000/api/products/${id}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${user.token}` },
    });
    fetchProducts();
  };

  return (
    <div className="admin-page">
      <div className="container">
        <h1 className="admin-title">🛠 Admin Panel</h1>

        {/* ── ADD / EDIT FORM ── */}
        <div className="admin-form-card">
          <h2>{editId ? 'Edit Product' : 'Add New Product'}</h2>
          {msg && <div className="admin-msg">{msg}</div>}
          <form onSubmit={handleSubmit} className="admin-form">
            <div className="form-row">
              <div className="admin-field">
                <label>Product Name *</label>
                <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} required placeholder="e.g. 4K Smart TV 55inch" />
              </div>
              <div className="admin-field">
                <label>Category *</label>
                <select value={form.category} onChange={e => setForm({...form, category: e.target.value})} required>
                  <option value="">Select category</option>
                  {categories.map(c => <option key={c}>{c}</option>)}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="admin-field">
                <label>Price (₹) *</label>
                <input type="number" value={form.price} onChange={e => setForm({...form, price: e.target.value})} required placeholder="45999" />
              </div>
              <div className="admin-field">
                <label>Original Price (₹)</label>
                <input type="number" value={form.originalPrice} onChange={e => setForm({...form, originalPrice: e.target.value})} placeholder="65000" />
              </div>
              <div className="admin-field">
                <label>Stock</label>
                <input type="number" value={form.stock} onChange={e => setForm({...form, stock: e.target.value})} placeholder="50" />
              </div>
            </div>

            <div className="form-row">
              <div className="admin-field">
                <label>Badge</label>
                <select value={form.badge} onChange={e => setForm({...form, badge: e.target.value})}>
                  <option value="">None</option>
                  <option>Hot</option>
                  <option>New</option>
                  <option>Best Seller</option>
                </select>
              </div>
              <div className="admin-field">
                <label>Rating (0-5)</label>
                <input type="number" min="0" max="5" step="0.1" value={form.rating} onChange={e => setForm({...form, rating: e.target.value})} placeholder="4.5" />
              </div>
              <div className="admin-field admin-check">
                <label>
                  <input type="checkbox" checked={form.featured} onChange={e => setForm({...form, featured: e.target.checked})} />
                  Featured Product
                </label>
              </div>
            </div>

            <div className="admin-field">
              <label>Description</label>
              <textarea value={form.description} onChange={e => setForm({...form, description: e.target.value})} rows={3} placeholder="Product description..." />
            </div>

            <div className="admin-field">
              <label>Image URL</label>
              <input value={form.image} onChange={e => setForm({...form, image: e.target.value})} placeholder="https://..." />
            </div>

            <div className="admin-form-actions">
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? 'Saving...' : editId ? 'Update Product' : 'Add Product'}
              </button>
              {editId && (
                <button type="button" className="btn-outline" onClick={() => { setForm(emptyForm); setEditId(null); }}>
                  Cancel
                </button>
              )}
            </div>
          </form>
        </div>

        {/* ── PRODUCT TABLE ── */}
        <div className="admin-table-card">
          <h2>All Products ({products.length})</h2>
          <div className="admin-table-wrap">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Category</th>
                  <th>Price</th>
                  <th>Stock</th>
                  <th>Featured</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {products.map(p => (
                  <tr key={p._id}>
                    <td>{p.name}</td>
                    <td>{p.category}</td>
                    <td>₹{p.price?.toLocaleString('en-IN')}</td>
                    <td>{p.stock ?? '-'}</td>
                    <td>{p.featured ? '✅' : '—'}</td>
                    <td>
                      <button className="edit-btn"   onClick={() => handleEdit(p)}>Edit</button>
                      <button className="delete-btn" onClick={() => handleDelete(p._id)}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Admin;
